import java.io.*;

public class Main {
    // Checked: extends Exception, compiler forces handle-or-declare
    static class InsufficientFunds extends Exception {
        InsufficientFunds(String m) { super(m); }
    }

    static void withdraw(int balance, int amount) throws InsufficientFunds {
        if (amount > balance) throw new InsufficientFunds("need " + (amount - balance) + " more");
    }

    static void setAge(int age) {
        // Unchecked: programming error / broken contract, no throws clause needed
        if (age < 0) throw new IllegalArgumentException("age < 0: " + age);
    }

    public static void main(String[] args) {
        try {
            withdraw(50, 80); // caller MUST handle or declare
        } catch (InsufficientFunds e) {
            System.out.println("checked   -> " + e.getMessage());
        }
        try {
            setAge(-3);
        } catch (IllegalArgumentException e) {
            System.out.println("unchecked -> " + e.getMessage());
        }
        // Both are plain Throwables to the JVM; only javac cares
        System.out.println("InsufficientFunds is RuntimeException? "
            + (RuntimeException.class.isAssignableFrom(InsufficientFunds.class)));
        System.out.println("IllegalArgumentException is RuntimeException? "
            + (RuntimeException.class.isAssignableFrom(IllegalArgumentException.class)));
        System.out.println("IOException is RuntimeException? "
            + (RuntimeException.class.isAssignableFrom(IOException.class)));
    }
}

import java.io.*;
import java.sql.SQLException;

public class Main {
    // Walk up the superclass chain and print it
    static void chain(Class<?> c) {
        StringBuilder sb = new StringBuilder();
        for (Class<?> k = c; k != null; k = k.getSuperclass()) {
            if (sb.length() > 0) sb.append(" -> ");
            sb.append(k.getSimpleName());
        }
        System.out.println(sb);
    }

    static String kind(Class<?> c) {
        if (Error.class.isAssignableFrom(c)) return "Error";
        if (RuntimeException.class.isAssignableFrom(c)) return "unchecked";
        return "checked";
    }

    public static void main(String[] args) {
        Class<?>[] all = {
            NullPointerException.class, ArithmeticException.class,
            FileNotFoundException.class, SQLException.class,
            InterruptedException.class, OutOfMemoryError.class,
            StackOverflowError.class
        };
        for (Class<?> c : all) {
            System.out.print(kind(c) + ": ");
            chain(c);
        }
    }
}

public class Main {
    static int primitive() {
        int x = 1;
        try {
            return x;       // value 1 is saved here
        } finally {
            x = 99;         // too late: does not change the returned value
        }
    }

    static StringBuilder object() {
        StringBuilder sb = new StringBuilder("a");
        try {
            return sb;      // the reference is saved
        } finally {
            sb.append("b"); // mutating the same object IS visible
        }
    }

    @SuppressWarnings("finally")
    static int override() {
        try {
            throw new RuntimeException("lost");
        } finally {
            return 7;       // swallows the exception silently
        }
    }

    public static void main(String[] args) {
        System.out.println("primitive: " + primitive());
        System.out.println("object:    " + object());
        System.out.println("override:  " + override());
        for (int i = 0; i < 3; i++) {
            try {
                if (i == 1) continue;   // finally still runs
                System.out.println("body " + i);
            } finally {
                System.out.println("finally " + i);
            }
        }
        try {
            System.out.println("exiting");
            System.exit(0);             // finally does NOT run
        } finally {
            System.out.println("never printed");
        }
    }
}

public class Main {
    static class Res implements AutoCloseable {
        final String name;
        final boolean failOnClose;
        Res(String name, boolean failOnClose) {
            this.name = name; this.failOnClose = failOnClose;
            System.out.println("open " + name);
        }
        @Override public void close() {
            System.out.println("close " + name);
            if (failOnClose) throw new IllegalStateException("close failed: " + name);
        }
    }

    public static void main(String[] args) {
        try (Res a = new Res("A", false); Res b = new Res("B", true)) {
            System.out.println("body");
            throw new RuntimeException("body failed");
        } catch (RuntimeException e) {
            // Resources are already closed here (reverse order: B then A)
            System.out.println("caught: " + e.getMessage());
            for (Throwable s : e.getSuppressed()) {
                // close() failure is attached, not replacing the primary
                System.out.println("suppressed: " + s.getMessage());
            }
        } finally {
            System.out.println("finally");
        }
        // null resources are skipped, no NPE on close
        try (Res n = null) {
            System.out.println("null resource ok");
        }
    }
}

public class Main {
    // Unchecked base with an error code; sealed so switch is exhaustive
    sealed interface AppError permits NotFound, Conflict, DependencyDown {}

    static abstract class AppException extends RuntimeException {
        final String code;
        AppException(String code, String msg, Throwable cause) { super(msg, cause); this.code = code; }
    }
    static final class NotFound extends AppException implements AppError {
        NotFound(String what, long id) { super("NOT_FOUND", what + " " + id + " not found", null); }
    }
    static final class Conflict extends AppException implements AppError {
        Conflict(String msg) { super("CONFLICT", msg, null); }
    }
    static final class DependencyDown extends AppException implements AppError {
        DependencyDown(String msg, Throwable cause) { super("DEP_DOWN", msg, cause); }
    }

    // One central mapping to HTTP status; compiler checks all cases covered
    static int toHttp(AppError e) {
        return switch (e) {
            case NotFound n -> 404;
            case Conflict c -> 409;
            case DependencyDown d -> 503;
        };
    }

    public static void main(String[] args) {
        AppException[] errs = {
            new NotFound("order", 42), new Conflict("email taken"),
            new DependencyDown("db timeout", new java.io.IOException("socket"))
        };
        for (AppException e : errs) {
            System.out.println(toHttp((AppError) e) + " " + e.code + " " + e.getMessage());
        }
    }
}

import java.sql.SQLException;

public class Main {
    static class DataAccessException extends RuntimeException {
        DataAccessException(String m, Throwable cause) { super(m, cause); }
    }

    static void repository() {
        try {
            throw new SQLException("connection refused");   // low level
        } catch (SQLException e) {
            // translate at the layer boundary but KEEP the cause
            throw new DataAccessException("loading order 42", e);
        }
    }

    static void badRepository() {
        try {
            throw new SQLException("connection refused");
        } catch (SQLException e) {
            throw new DataAccessException(e.getMessage(), null); // cause lost
        }
    }

    public static void main(String[] args) {
        try {
            repository();
        } catch (DataAccessException e) {
            System.out.println("top:   " + e);
            Throwable root = e;
            while (root.getCause() != null) root = root.getCause();
            System.out.println("root:  " + root);
        }
        try {
            badRepository();
        } catch (DataAccessException e) {
            System.out.println("cause when lost: " + e.getCause());
        }
    }
}

import java.util.*;

public class Main {
    static int parseBad(String s) {
        try {
            return Integer.parseInt(s);
        } catch (Exception e) {
            // anti-pattern: swallowed, returns a fake value
            return 0;
        }
    }

    static Optional<Integer> parseGood(String s) {
        // normal "not a number" is not exceptional: return Optional
        try {
            return Optional.of(Integer.parseInt(s));
        } catch (NumberFormatException e) {
            return Optional.empty();
        }
    }

    static void wrapBad() {
        try {
            Integer.parseInt("x1");
        } catch (NumberFormatException e) {
            throw new RuntimeException(e.getMessage()); // cause lost
        }
    }

    static void wrapGood() {
        try {
            Integer.parseInt("x1");
        } catch (NumberFormatException e) {
            throw new IllegalStateException("bad config port", e); // cause kept
        }
    }

    public static void main(String[] args) {
        System.out.println("bad:  " + parseBad("abc") + " (looks like real zero)");
        System.out.println("good: " + parseGood("abc") + " " + parseGood("12"));
        try { wrapBad(); } catch (RuntimeException e) {
            System.out.println("wrapBad cause:  " + e.getCause());
        }
        try { wrapGood(); } catch (RuntimeException e) {
            System.out.println("wrapGood cause: " + e.getCause());
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Thread worker = new Thread(() -> {
            try {
                Thread.sleep(5000);             // blocking call
                System.out.println("worker finished normally");
            } catch (InterruptedException e) {
                // sleep cleared the flag when it threw
                System.out.println("flag after catch: " + Thread.currentThread().isInterrupted());
                Thread.currentThread().interrupt(); // restore it for callers up the stack
                System.out.println("flag restored:   " + Thread.currentThread().isInterrupted());
                System.out.println("worker exits promptly");
            }
        });
        worker.start();
        Thread.sleep(100);
        worker.interrupt();                     // cooperative cancel request
        worker.join();

        // interrupted() reads AND clears; isInterrupted() only reads
        Thread.currentThread().interrupt();
        System.out.println("isInterrupted: " + Thread.currentThread().isInterrupted());
        System.out.println("interrupted(): " + Thread.interrupted());
        System.out.println("after clear:   " + Thread.currentThread().isInterrupted());
    }
}

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] data = "line one\nline two\nline three".getBytes(StandardCharsets.UTF_8);

        // java.io: blocking streams composed with decorators
        try (BufferedReader r = new BufferedReader(new InputStreamReader(
                new ByteArrayInputStream(data), StandardCharsets.UTF_8))) {
            String line;
            int n = 0;
            while ((line = r.readLine()) != null) {
                n++;
                System.out.println("io  " + n + ": " + line);
            }
        }

        // java.nio: a channel reads into a buffer you control
        try (ReadableByteChannel ch = Channels.newChannel(new ByteArrayInputStream(data))) {
            ByteBuffer buf = ByteBuffer.allocate(10);
            int total = 0, reads = 0;
            while (ch.read(buf) != -1) {
                buf.flip();                 // switch buffer from write mode to read mode
                total += buf.remaining();
                reads++;
                buf.clear();                // ready for the next fill
            }
            System.out.println("nio read " + total + " bytes in " + reads + " reads of <= 10");
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        // Stand-in for a huge file: a few lines in memory
        String log = "10.0.0.1 GET /a\n10.0.0.2 GET /b\n10.0.0.1 GET /c\n"
                   + "bad-line\n10.0.0.3 GET /d\n10.0.0.1 GET /e\n10.0.0.2 GET /f\n";
        Map<String, Integer> counts = new HashMap<>();
        int bad = 0;
        // One line at a time; memory holds only the counters
        try (BufferedReader r = new BufferedReader(new StringReader(log))) {
            String line;
            while ((line = r.readLine()) != null) {
                String[] p = line.split(" ");
                if (p.length < 3) { bad++; continue; }   // count bad records, do not crash
                counts.merge(p[0], 1, Integer::sum);
            }
        }
        // Top-K with a min-heap of size K: O(n log K)
        int k = 2;
        PriorityQueue<Map.Entry<String, Integer>> heap =
            new PriorityQueue<>(Comparator.comparingInt(Map.Entry::getValue));
        for (Map.Entry<String, Integer> e : counts.entrySet()) {
            heap.add(e);
            if (heap.size() > k) heap.poll();            // drop the smallest
        }
        List<Map.Entry<String, Integer>> top = new ArrayList<>(heap);
        top.sort((a, b) -> b.getValue() - a.getValue());
        System.out.println("bad lines: " + bad);
        for (Map.Entry<String, Integer> e : top) System.out.println(e.getKey() + " " + e.getValue());
    }
}

import java.io.*;

public class Main {
    static class User implements Serializable {
        private static final long serialVersionUID = 1L; // explicit version stamp
        String name = "ann";
        int age = 30;
    }

    static byte[] write(Object o) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bos)) { out.writeObject(o); }
        return bos.toByteArray();
    }

    public static void main(String[] args) throws Exception {
        byte[] bytes = write(new User());
        System.out.println("serialized " + bytes.length + " bytes");
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            User u = (User) in.readObject();
            System.out.println("read back: " + u.name + " " + u.age);
        }
        // Simulate an incompatible version: change the UID bytes in the stream.
        // The 8-byte UID follows the class name in the descriptor.
        String cn = User.class.getName();
        int pos = new String(bytes, "ISO-8859-1").indexOf(cn) + cn.length();
        bytes[pos + 7] = 2;                       // 1L -> 2L
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            in.readObject();
        } catch (InvalidClassException e) {
            System.out.println("mismatch -> InvalidClassException");
        }
    }
}

import java.io.*;

public class Main {
    static class Session implements Serializable {
        private static final long serialVersionUID = 1L;
        String user = "ann";
        transient String password = "secret";   // skipped by serialization
        transient int cacheSize = 5;            // derived value
        static int counter = 42;                // static is never serialized

        // Called during deserialization to rebuild transient state
        private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
            in.defaultReadObject();             // restore normal fields first
            cacheSize = user.length() * 10;     // recompute derived state
        }
    }

    public static void main(String[] args) throws Exception {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bos)) { out.writeObject(new Session()); }
        Session.counter = 0;                    // static stays whatever it is now
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bos.toByteArray()))) {
            Session s = (Session) in.readObject();
            System.out.println("user      = " + s.user);
            System.out.println("password  = " + s.password + " (default null)");
            System.out.println("cacheSize = " + s.cacheSize + " (rebuilt)");
            System.out.println("counter   = " + Session.counter + " (static untouched)");
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Evil implements Serializable {
        private static final long serialVersionUID = 1L;
        private void readObject(ObjectInputStream in) {
            System.out.println("!!! readObject hook ran before app code saw the object");
        }
    }

    static byte[] write(Object o) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bos)) { out.writeObject(o); }
        return bos.toByteArray();
    }

    static void read(byte[] b, ObjectInputFilter f) {
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(b))) {
            if (f != null) in.setObjectInputFilter(f);
            System.out.println("read -> " + in.readObject().getClass().getSimpleName());
        } catch (Exception e) {
            System.out.println("blocked -> " + e.getClass().getSimpleName());
        }
    }

    public static void main(String[] args) throws Exception {
        byte[] evil = write(new Evil());
        byte[] safe = write(new ArrayList<>(List.of("a", "b")));
        System.out.println("-- no filter --");
        read(evil, null);                                   // hook runs: dangerous
        // allow-list: only java.util.* and java.lang.*, reject everything else
        ObjectInputFilter allow = ObjectInputFilter.Config.createFilter("java.util.*;java.lang.*;!*");
        System.out.println("-- allow-list filter --");
        read(safe, allow);
        read(evil, allow);
    }
}

import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        // 1) Raw thread: exception goes to the uncaught handler, kills only that thread
        Thread t = new Thread(() -> { throw new IllegalStateException("thread boom"); });
        t.setUncaughtExceptionHandler((th, ex) -> System.out.println("handler got: " + ex.getMessage()));
        t.start(); t.join();

        ExecutorService ex = Executors.newSingleThreadExecutor();
        // 2) submit: exception is captured in the Future, silent until get()
        Future<Integer> f = ex.submit(() -> { throw new IllegalStateException("task boom"); });
        try {
            f.get();
        } catch (ExecutionException e) {
            System.out.println("get() wrapped: " + e.getCause().getMessage());
        }
        ex.shutdown();

        // 3) CompletableFuture: join() wraps in CompletionException
        CompletableFuture<Integer> cf = CompletableFuture.supplyAsync(() -> {
            throw new IllegalArgumentException("cf boom");
        });
        try {
            cf.join();
        } catch (CompletionException e) {
            System.out.println("join() wrapped: " + e.getCause().getMessage());
        }
        // exceptionally receives the (wrapped) exception and returns a fallback value
        int v = CompletableFuture.<Integer>supplyAsync(() -> { throw new IllegalArgumentException("x"); })
            .exceptionally(e -> -1).join();
        System.out.println("fallback value: " + v);
    }
}
